//! DISCLAIMER: This example was generated by GPT-6 high.

use fastxfix::CommonStr;
use rayon::{ThreadPool, ThreadPoolBuilder};
use std::{hint::black_box, time::Instant};

const SAMPLES: usize = 3; // measured samples, after one warm-up
const REPEATS: usize = 7; // operations per sample

#[derive(Clone, Copy)]
enum Mode {
    Prefix,
    Suffix,
}

fn make_input(count: usize, shared_len: usize, extra_len: usize, mode: Mode) -> Vec<String> {
    use ya_rand::*;
    let mut rng = ShiroRng::default();
    let shared = "X".repeat(shared_len);
    (0..count)
        .map(|_| {
            // Different strings, reproducible and generated outside the timer.
            let variation: String = (0..extra_len)
                // I modified this because chatgpt is an idiot.
                //.map(|j| (b'a' + ((i.wrapping_mul(17) ^ j.wrapping_mul(11)) % 26) as u8) as char)
                .map(|_| rng.ascii_lowercase())
                .collect();
            match mode {
                Mode::Prefix => format!("{shared}{variation}"),
                Mode::Suffix => format!("{variation}{shared}"),
            }
        })
        .collect()
}

// Straightforward, single-threaded reference implementation.
// Uses bytes, then corrects to valid UTF-8 boundaries, just like fastxfix.
fn scalar(input: &[String], mode: Mode) -> Option<&str> {
    let mut result = input.first()?.as_str();
    for s in input.iter().skip(1) {
        match mode {
            Mode::Prefix => {
                let mut end = result
                    .bytes()
                    .zip(s.bytes())
                    .take_while(|(a, b)| a == b)
                    .count();
                while !result.is_char_boundary(end) {
                    end -= 1;
                }
                result = &result[..end];
            }
            Mode::Suffix => {
                let matched = result
                    .bytes()
                    .rev()
                    .zip(s.bytes().rev())
                    .take_while(|(a, b)| a == b)
                    .count();
                let mut start = result.len() - matched;
                while !result.is_char_boundary(start) {
                    start += 1;
                }
                result = &result[start..];
            }
        }
        if result.is_empty() {
            return None;
        }
    }
    (!result.is_empty()).then_some(result)
}

fn optimized(input: &Vec<String>, mode: Mode) -> Option<&str> {
    match mode {
        Mode::Prefix => input.common_prefix_ref(),
        Mode::Suffix => input.common_suffix_ref(),
    }
}

fn time(mut f: impl FnMut() -> Option<usize>) -> f64 {
    let start = Instant::now();
    for _ in 0..REPEATS {
        black_box(f());
    }
    start.elapsed().as_secs_f64() * 1_000_000.0 / REPEATS as f64
}

fn median(mut f: impl FnMut() -> f64) -> f64 {
    f(); // warm-up
    let mut samples: Vec<_> = (0..SAMPLES).map(|_| f()).collect();
    samples.sort_by(f64::total_cmp);
    samples[SAMPLES / 2]
}

fn bench(
    label: &str,
    count: usize,
    shared: usize,
    extra: usize,
    mode: Mode,
    single_thread: &ThreadPool,
) {
    let input = make_input(count, shared, extra, mode);
    let expected = scalar(&input, mode);
    assert_eq!(
        expected,
        optimized(&input, mode),
        "{label}: incorrect result"
    );

    let scalar_us = median(|| time(|| scalar(black_box(&input), mode).map(str::len)));
    let one_us = median(|| {
        time(|| single_thread.install(|| optimized(black_box(&input), mode).map(str::len)))
    });
    let multi_us = median(|| time(|| optimized(black_box(&input), mode).map(str::len)));

    println!("{label}: {count} strings, {} bytes/string", shared + extra);
    println!("  scalar reference:  {scalar_us:9.2} us");
    println!(
        "  fastxfix, 1 thread:{one_us:9.2} us  ({:.2}x vs scalar)",
        scalar_us / one_us
    );
    println!(
        "  fastxfix, default: {multi_us:9.2} us  ({:.2}x vs scalar)",
        scalar_us / multi_us
    );
    println!();
}

fn main() {
    let one = ThreadPoolBuilder::new().num_threads(1).build().unwrap();
    println!("Rayon default threads: {}\n", rayon::current_num_threads());

    // Separate short vs long matches and prefix vs suffix.
    // The no-match case exposes Rayon scheduling overhead / early exit.
    bench("tiny prefix", 8, 1024, 32, Mode::Prefix, &one);
    bench("short prefix", 32_768, 32, 64, Mode::Prefix, &one);
    bench("long prefix", 32_768, 1024, 32, Mode::Prefix, &one);
    bench("long suffix", 32_768, 1024, 32, Mode::Suffix, &one);
    bench("no common prefix", 32_768, 0, 128, Mode::Prefix, &one);

    // Cache-friendly: useful for isolating SIMD improvements.
    bench("SIMD prefix / 8 MiB", 128, 65_504, 32, Mode::Prefix, &one);
    bench("SIMD suffix / 8 MiB", 128, 65_504, 32, Mode::Suffix, &one);

    // Intermediate workloads.
    bench(
        "SIMD prefix / 64 MiB",
        1_024,
        65_504,
        32,
        Mode::Prefix,
        &one,
    );
    bench(
        "SIMD suffix / 64 MiB",
        1_024,
        65_504,
        32,
        Mode::Suffix,
        &one,
    );

    bench(
        "SIMD prefix / 256 MiB",
        4_096,
        65_504,
        32,
        Mode::Prefix,
        &one,
    );
    bench(
        "SIMD suffix / 256 MiB",
        4_096,
        65_504,
        32,
        Mode::Suffix,
        &one,
    );

    // Large streaming workloads.
    bench(
        "SIMD prefix / 1 GiB",
        16_384,
        65_504,
        32,
        Mode::Prefix,
        &one,
    );

    // Approximately 2.00 GB (1,998,848,000 bytes).
    bench("SIMD prefix / 2 GB", 30_500, 65_504, 32, Mode::Prefix, &one);
    bench("SIMD suffix / 2 GB", 30_500, 65_504, 32, Mode::Suffix, &one);
}
